with question_expected(rid,qid,stimulus_md5,prompt_md5,key,qtype,eid,style) as (values
(E'a120b576-079e-416f-ab8f-689fcc0afc42',E'PT132-S2-Q3',E'7645615090d93d1226ba2101f283bf41',E'830d800608ba4fe92f1671884723e95e',E'B',E'Strengthen',E'ac574eb4-f700-4220-91ae-c2fd4783e199',E'single')),
choice_expected(rid,letter,body_md5,correct) as (values
(E'ea23a667-b0cf-4427-9746-6decd26f2110',E'A',E'cf9bd3a3c6bf0f13e3ad93026ac3fb4b',E'false'),
(E'40f00a2b-ef4a-4567-a028-4ef2e201cac9',E'B',E'5fdbccaaddad614f6f81ef3314cad1f0',E'true'),
(E'2d091b90-e57e-4520-8c79-2d62be1d4e13',E'C',E'46258e5c8b8c1483720223ff84d68042',E'false'),
(E'd33fa458-cbfb-4ba5-b6f8-e6096326874b',E'D',E'e26b73608645d99dbc8de4a2cc896fe6',E'false'),
(E'32b0b3e7-77ba-4f4f-9c1b-ae78b4617df7',E'E',E'554c3530cacefcc2dc0934b55aeeb0dc',E'false')),
body_expected(kind,rid,slot,label,old_text,old_md5,new_text,new_md5,target) as (values
(E'step',E'41eff948-d99b-4ede-b6e1-9d513e0de2f8',E'0',E'Evidence',E'Medications with an unpleasant taste are generally produced only in tablet, capsule, or soft-gel form.\nPT → (T or C or SG)\n\nThe active ingredient in medication M is a waxy substance that cannot tolerate the heat used to manufacture tablets because it has a low melting point.\n~T\n\nThe company developing M does not have soft-gel manufacturing technology and manufactures all its medications itself.\n~SG',E'41fbdb0fb68260cf91a839602ba59e59',E'Medications with an unpleasant taste are generally produced only in tablet, capsule, or soft-gel form.\n\nThe active ingredient in medication M is a waxy substance that cannot tolerate the heat used to manufacture tablets because it has a low melting point.\n\nThe company developing M does not have soft-gel manufacturing technology and manufactures all its medications itself.',E'c52c23e63777dcff31fddb783cedd1d6',E'true'),
(E'step',E'bfdc099c-b881-48a9-a793-c558726d8a4a',E'1',E'Conclusion',E'M will most likely be produced in capsule form.\nC',E'b80c1b4cfb978cb10c8fcbcdabfa84f8',E'M will most likely be produced in capsule form.',E'09ed6af65842fe3ac97520b420a6cfdd',E'true'),
(E'step',E'dfe89858-b232-4a53-b9da-12973ec59c10',E'2',E'Evaluate',E'The conclusion follows a process of elimination. Medications with an unpleasant taste are "generally produced only in tablet, capsule, or soft-gel form." M can''t be a tablet, because its waxy ingredient can''t take the heat. M can''t be a soft-gel, because the company "does not have soft-gel manufacturing technology" and makes everything itself. Capsule is what''s left.\n\nBut look at who the first rule covers: only medications with an unpleasant taste. Nothing tells us M tastes bad. If M tastes fine, the rule never applies, and M could come in a liquid, a powder, or anything else. The elimination only works if M is in the group the rule covers.\nPT → (T or C or SG)\n~T\n~SG\nmissing: PT',E'6594fb8982722c5f1925afab0e0c4adf',E'The argument narrows the options. M cannot be a tablet, because its waxy ingredient cannot tolerate the heat. M cannot be a soft-gel, because the company lacks that technology and makes all its medications itself.\n\nWhat would make capsule the likely choice? Medications with an unpleasant taste generally come in one of those three forms. But nothing tells us M has an unpleasant taste. Without that connection, the usual pattern gives us no reason to expect M to come in one of the three forms.\n\nIf M tastes unpleasant, the pattern applies to it. Two of the usual forms are ruled out, which supports capsule as the most likely remaining form. Notice the limit: "generally" allows exceptions. We are supporting "most likely," not proving that a capsule is the only possible outcome.',E'1110270c8874c745b97711fcce368f87',E'true'),
(E'step',E'a65bed50-5aa2-42be-9d04-2abc72aa56fd',E'3',E'Goal',E'The stem says "if which one of the following is assumed", so we want the piece that makes the conclusion follow. The missing piece is the rule''s trigger: M has an unpleasant taste. Once that''s in place, the three-option rule applies, two options are gone, and capsule is the one left.',E'79bf7d390e41204b0242b1abc060d3f9',E'The stem asks what would most strongly support the conclusion if assumed. Look for the fact that connects M to the usual three-form pattern: M has an unpleasant taste. Then ruling out tablet and soft-gel gives us a reason to expect capsule. It strengthens the conclusion without turning "most likely" into a guarantee.',E'853378630b1e5600558cb56c47d37294',E'true'),
(E'note',E'63ff81ea-97b3-4c18-979e-d96f1723e02f',E'A',NULL,E'If M can be made as a liquid, that adds a fourth option outside tablet, capsule, and soft-gel. That makes capsule less certain, not more. It also does nothing to show that M tastes unpleasant, so the three-option rule still isn''t triggered.',E'3b2072c08abacf895510d9c672c017ab',E'If M can be made as a liquid, that gives us another possible form, not a reason to favor capsule. A also does not tell us M tastes unpleasant, so it does not connect M to the usual tablet, capsule, or soft-gel pattern.',E'2cbb95a83f9e22338f48a7820d156959',E'true'),
(E'note',E'47fe78f1-cd86-492d-b1cf-bb1b3decbfd2',E'B',NULL,E'This is the missing trigger. With M tasting unpleasant, the first premise applies: M will generally come as a tablet, capsule, or soft-gel. The heat rules out tablet, the company''s missing technology rules out soft-gel, and capsule is what remains.\nPT → (T or C or SG)\nPT, ~T, ~SG, so C\n\nThe move: when an argument eliminates options from a rule, check that the rule actually applies to the thing in the conclusion.',E'a021aa9db386c33ebd78ff19817711b9',E'This connects M to the general pattern. If M has an unpleasant taste, we have a reason to expect tablet, capsule, or soft-gel. The ingredient rules out tablet, and the company cannot make soft-gels, so capsule becomes the likely choice.\n\nKeep the qualification: the premise says "generally," so the answer supports "most likely" rather than guaranteeing capsule. When an argument narrows the usual options, check that the case fits the group described.',E'26171ec42bec950554ff99b1ab5e0ed1',E'true'),
(E'note',E'd1cd2901-904c-49c5-853a-013b60d5475a',E'C',NULL,E'This says a capsule medication isn''t also a soft-gel (C → ~SG). We already know M won''t be a soft-gel, so this adds nothing. And it still doesn''t tell us M is limited to the three forms, because nothing says M tastes unpleasant.',E'20e37f1596033e16283b1d615dfadf5e',E'This says a capsule medication is not also a soft-gel (C → ~SG). We already know M will not be a soft-gel, so this adds nothing. It also does not establish that M fits the general three-form pattern, because nothing says M tastes unpleasant.',E'6a0ce9a257f7cf125a341672216b040c',E'true'),
(E'note',E'242195a2-95b6-484f-b56e-d57bc5cb503b',E'D',NULL,E'If most low-melting-point medications are soft-gels, that points M toward a form this company can''t make. It gives no reason to think M ends up as a capsule, and it never puts M under the unpleasant-taste rule.',E'9b29b7a714bdd7fc17115a5ed80bc17f',E'If most low-melting-point medications are soft-gels, that points M toward a form this company can''t make. It gives no reason to think M ends up as a capsule, and it never puts M under the unpleasant-taste rule.',E'9b29b7a714bdd7fc17115a5ed80bc17f',E'false'),
(E'note',E'ef879f8c-59b5-47d1-a3e0-9cfd7646a061',E'E',NULL,E'This gives a reason to choose capsules for bad-tasting medicine, but it only matters if M tastes bad. E never says it does. Without that, M isn''t covered by the rule and could be produced in a form outside the three listed.',E'2f739507c3328718a9f0d318ddd4082f',E'This gives a reason to choose capsules for bad-tasting medicine, but it only matters if M tastes bad. E never says it does. Without that, M isn''t covered by the rule and could be produced in a form outside the three listed.',E'2f739507c3328718a9f0d318ddd4082f',E'false')),

locked_question as materialized(select q.* from lr_questions q where q.qid=E'PT132-S2-Q3' for update),
locked_explanation as materialized(select e.* from lr_explanations e where e.question_id in(select id from locked_question) for update),
locked_choices as materialized(select c.* from lr_answer_choices c where c.question_id in(select id from locked_question) for update),
locked_steps as materialized(select s.* from lr_explanation_steps s where s.explanation_id in(select id from locked_explanation) for update),
locked_notes as materialized(select n.* from lr_explanation_choice_notes n where n.explanation_id in(select id from locked_explanation) for update),
actual_bodies as (
 select 'step'::text kind,s.id::text rid,s.position::text slot,s.label,s.body from locked_steps s
 union all select 'note',n.id::text,n.letter::text,null::text,n.body from locked_notes n),
eligibility as materialized(select
 (select count(*) from locked_question)=1 and (select count(*) from locked_explanation)=1
 and (select count(*) from locked_choices)=5 and (select count(*) from actual_bodies)=9
 and (select count(*) from locked_question q join locked_explanation e on e.question_id=q.id join question_expected x on x.rid=q.id::text where q.qid=x.qid and md5(q.stimulus)=x.stimulus_md5 and md5(q.prompt)=x.prompt_md5 and q.correct_choice::text=x.key and q.question_type=x.qtype and e.id::text=x.eid and e.style=x.style)=1
 and not exists(select 1 from choice_expected x where (select count(*) from locked_choices c where c.id::text=x.rid and c.letter::text=x.letter and md5(c.choice_text)=x.body_md5 and c.is_correct=x.correct::boolean)<>1)
 and not exists(select 1 from body_expected x where (select count(*) from actual_bodies a where a.kind=x.kind and a.rid=x.rid and a.slot=x.slot and (x.label is null or a.label=x.label) and a.body=x.old_text and md5(a.body)=x.old_md5)<>1) eligible)
,
us as(update lr_explanation_steps t set body=x.new_text from body_expected x,question_expected q,eligibility g
 where g.eligible and x.target::boolean and x.kind=E'step' and t.id=x.rid::uuid and t.explanation_id=q.eid::uuid
 and t.position::text=x.slot and t.label=x.label and t.body=x.old_text and md5(t.body)=x.old_md5
 returning t.id::text rid,md5(t.body) body_md5),
un as(update lr_explanation_choice_notes t set body=x.new_text from body_expected x,question_expected q,eligibility g
 where g.eligible and x.target::boolean and x.kind=E'note' and t.id=x.rid::uuid and t.explanation_id=q.eid::uuid
 and t.letter::text=x.slot and t.body=x.old_text and md5(t.body)=x.old_md5
 returning t.id::text rid,md5(t.body) body_md5),
writes as(select * from us union all select * from un),
result as(select (select eligible from eligibility) eligible,(select count(*) from us) updated_steps,(select count(*) from un) updated_notes,
 (select count(*) from writes) updated_rows,(select count(*) from writes w join body_expected x on x.rid=w.rid and x.new_md5=w.body_md5) verified_rows,
 (select jsonb_agg(to_jsonb(w)) from writes w) receipts)
select *,1/(case when (not eligible and updated_rows=0) or (eligible and updated_rows=7 and verified_rows=7 and updated_steps=4 and updated_notes=3) then 1 else 0 end) atomic_assertion from result;
